from pathlib import Path
from html import escape as e
from datetime import date
import json

BASE='https://kanlerxz87-cyber.github.io/DIYHOME2/'
DAY='2026-11-20'
AG='https://affiliate-program.amazon.com/help/operating/agreement'
POL='https://affiliate-program.amazon.com/help/operating/policies'
FTC='https://www.ftc.gov/business-guidance/resources/ftcs-endorsement-guides-what-people-are-asking'
SC='https://search.google.com/search-console/'
PAGES='https://docs.github.com/en/pages/getting-started-with-github-pages/about-github-pages'
products=[('B0hmGG4m2','B08FKW9JRM','Wallpaper smoothing kit','Walls & finishes','How do you choose a wallpaper smoothing tool?','Check the wallcovering manufacturer’s recommended applicator before buying. Compare edge shape and stiffness, then try the tool on a scrap. Plan how you’ll reach inside corners and trim around outlets before starting.'),('B03QDuGdo','B0BSKQW2T2','Under-cabinet paper towel holder','Kitchen organization','Adhesive or screw mount: what fits your kitchen?','Measure a full roll, including room to slide it on and off. Open the neighboring cabinet door and check what it would hit. Compare the maker’s surface and mounting instructions with your cabinet finish and lease restrictions.'),('B0hpD2JGQ','B08DY9HRWD','Adjustable pots and pans rack','Kitchen organization','Will a cookware rack fit your cabinet?','Measure the usable cabinet opening, not just the outside width. Include hinges and shelf lips. Lay out your largest pan and lid with their handles extended, then compare that footprint with the rack’s documented limits.')]
nav={'guides.html':'Buying guides','walls.html':'Walls & finishes','kitchen.html':'Kitchen organization'}
studio={'summary.html':'Executive summary','review.html':'Flagged for Review','measurement.html':'Measurement','privacy.html':'Privacy'}
links=lambda xs: ''.join(f'<a href="{k}">{e(v)}</a>' for k,v in xs.items())
def ref(url,title='Official source'):
    rel=' rel="sponsored"' if url.startswith('https://www.amazon.com/dp/') else ''
    return f'<a href="{e(url)}"{rel}>{e(title)}</a>'
def dp(asin): return 'https://www.amazon.com/dp/'+asin

def page(path,title,desc,body,noindex=False):
    Path(path).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{e(desc)}"><meta name="referrer" content="no-referrer"><title>{e(title)} | DIY Home</title><link rel="canonical" href="{BASE if path=='index.html' else BASE+path}"><link rel="alternate" type="application/rss+xml" title="DIY Home" href="feed.xml"><link rel="stylesheet" href="style.css"><script src="metrics.js" defer></script>{'<meta name="robots" content="noindex">' if noindex else ''}</head><body><header><a class="brand" href="index.html"><span>⌂</span> DIY Home<span class="dot">.</span></a><nav aria-label="Main">{links(nav)}<details><summary>Studio</summary><div>{links(studio)}</div></details></nav></header><aside class="disclosure">As an Amazon Associate I earn from qualifying purchases.</aside><main id="main">{body}</main><footer><a class="brand" href="index.html">DIY Home.</a><p>As an Amazon Associate I earn from qualifying purchases.</p><nav aria-label="Footer">{links(studio)}<a href="feed.xml">RSS feed</a></nav></footer></body></html>''',encoding='utf-8')

def intro(label,title,desc): return f'<section class="intro"><p class="eyebrow">{label}</p><h1>{title}</h1><p>{desc}</p></section>'
def cards(rows):
    return '<div class="cards">'+''.join(f'<article><p class="eyebrow">0{products.index(p)+1} / {p[3]}</p><h3>{p[2]}</h3><p>{p[4]}</p><a href="{p[1].lower()}.html">Read the guide →</a></article>' for p in rows)+'</div>'
page('index.html','Small upgrades, better everyday living','Practical buying guides for walls, kitchens and home organization.',f'''<section class="hero"><div><p class="eyebrow">THE PRACTICAL HOME EDIT</p><h1>Small upgrades.<br><em>Better living.</em></h1><p>Make the most of the space you already have. Start with practical picks for smoother walls and a kitchen that works better.</p><a class="button" href="#edit">Explore the edit →</a></div><img src="assets/home.jpg" alt="Illustrative sunlit kitchen with oak cabinets and open shelving" fetchpriority="high"></section><section id="edit"><p class="eyebrow">THE FIRST EDIT</p><h2>Three upgrades to consider</h2>{cards(products)}</section><section class="season"><p class="eyebrow">SEASONAL NOTE</p><h2>Make room for holiday cooking</h2><p>Start with the cabinet you open most often. Measure it before you shop for a rack or move a holder off the counter.</p><a href="kitchen.html">Explore kitchen organization →</a></section>''')
page('guides.html','Buying guides','Shop with better questions.',intro('THE LIBRARY','Buying guides','Measure first, compare thoughtfully, and buy only what fits.')+cards(products))
for cat,path in [('Walls & finishes','walls.html'),('Kitchen organization','kitchen.html')]:
    page(path,cat,'Practical upgrades and fit checks.',intro('THE HOME EDIT',e(cat),'Start with one small upgrade, then check fit and installation before buying.')+cards([p for p in products if p[3]==cat]))
for slug,asin,name,cat,title,text in products:
    page(asin.lower()+'.html',title,text,intro(e(cat),title,'By DIY Home Editorial · November 20, 2026')+f'<article class="prose"><p>{text}</p><h2>One listing to compare</h2><p>{name} was the destination observed on November 20, 2026. This is a listing-based guide, not a hands-on review. The submitted link is not published as an affiliate link.</p><p>{ref(dp(asin),"See the Amazon listing (reference only) →")}</p><p><a href="guides.html">All buying guides →</a></p></article>')

def table(headers,rows):
    return '<div class="scroll"><table><thead><tr>'+''.join(f'<th scope="col">{x}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
records=[]
for i,p in enumerate([products[0],products[1],products[1],products[2]],1):
    records.append(dict(entry=i,submitted='https://link.amazon/'+p[0],intended_asin=None,official_listing_url=None,confirmed_at=None,confirmation_source=None,observed_target=dp(p[1]),observed_at=DAY,special_link=None,tracking_report_confirmed_at=None,policy_review_source=None))
Path('product-register.json').write_text(json.dumps(records,indent=2)+'\n')
assert all(r['special_link'] is None for r in records), 'Affiliate publishing is locked pending enrolled workflow and policy review'
rows=[[str(r['entry']),e(r['submitted']),'','','','',ref(r['observed_target'],r['observed_target'].split('/')[-1]),DAY,('Duplicate of #2; ' if r['entry']==3 else '')+'Intent and attribution unverified'] for r in records]
page('review.html','Flagged for Review','Product intent and observed redirects are separate.',intro('STUDIO','Flagged for Review','Observed destinations are not evidence of intended products or working affiliate attribution. Blank fields are unverified.')+table(['#','Submitted URL','Intended ASIN','Official intended listing','Confirmed on','Confirmation source','Observed Amazon listing','Observed on','Flag'],rows)+table(['Issue','Disposition','Source'],[['Tracking ID shopnow047c-20','User-supplied, not authenticated. Special Links withheld; short-link compliance unresolved.',ref(AG)],['Air-fryer topics','Editorial hypotheses only; none of the observed listings was an air fryer.',ref(dp('B08DY9HRWD'))],['Prices, reviews and commission','Not republished or estimated. No authorized data feed or reports available.',ref(POL)],['Disclosure and endorsement context','Disclosure shipped; account-specific review pending.',ref(FTC)],['Search Console and reader capture','Property ownership not confirmed; RSS available without collecting email.',ref(SC)]]),True)
page('summary.html','Executive summary','Launch scope, findings and next decision.',intro('STUDIO','Executive summary','Launch with buyer-first guides. Keep affiliate attribution on hold until destinations and reporting are confirmed.')+table(['Area','Finding / decision','Source'],[['Catalog','Four submissions, three distinct short links. Start with walls and kitchen organization; neither cluster is a profitability claim.',ref(dp('B08FKW9JRM'))],['Monetization','No Special Links released. Confirm intended ASIN and official URL separately, generate one enrolled link per product, and verify destination and reporting before expansion.',ref(AG)],['Editorial','Target one question-led guide every two weeks after measurement is operational. Review query impressions and clicks monthly before choosing the next topic.',ref(SC)],['Automation','Build regenerates the feed and sitemap. AI research, ranking and automated publication are not active. Only use authorized inputs and keep a publication gate.',ref(POL)],['Hosting','Canonical publication uses GitHub Pages. Its static host cannot run the collector.',ref(PAGES)]]),True)
Path('campaign-ledger.csv').write_text('timestamp,source,channel,eligible_sessions,clicks,reported_orders,provenance\n')
page('measurement.html','Measurement','Event definitions and authorized campaign ledger.',intro('STUDIO','Measurement','The collector is available for self-hosting. GitHub Pages does not collect events; no live report or attribution data is available.')+table(['Event','Definition','Source'],[[key,desc,ref(src)] for key,desc,src in [('page_view','One browser event on page load.',PAGES),('guide_view','A guide page opens.',PAGES),('outbound_click','A reader activates a marked product link. A click is not an order.',AG),('rss_click','A reader activates the RSS link.',PAGES),('reported_order','Aggregate count from an authorized Associates report, never inferred from a browser action.',POL)]])+ '<h2>Campaign ledger</h2><p>No authorized report rows. <a href="campaign-ledger.csv">Download the empty ledger</a>.</p>',True)
page('privacy.html','Privacy','Measurement and reader privacy.',intro('STUDIO','Privacy','This Pages deployment does not send analytics events. RSS needs no account. Amazon and GitHub handle requests to their own services under their own policies.')+'<div class="prose"><p>The optional collector aggregates counts by UTC day, event and known page. It stores no cookies, IP addresses, referrers or individual event histories. Browser preferences for Global Privacy Control and Do Not Track are respected. Infrastructure may have separate request logs.</p></div>',True)
paths=['index.html',*nav,*[p[1].lower()+'.html' for p in products]]
Path('sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE+(x if x!="index.html" else "")}</loc></url>' for x in paths)+'</urlset>')
Path('feed.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>DIY Home</title><link>'+BASE+'</link><description>Practical buying guides for everyday upgrades.</description>'+''.join(f'<item><title>{e(p[4])}</title><link>{BASE+p[1].lower()}.html</link><guid>{BASE+p[1].lower()}.html</guid><description>{e(p[5])}</description><pubDate>Fri, 20 Nov 2026 00:00:00 GMT</pubDate></item>' for p in products)+'</channel></rss>')
